import { CdkOverlayOrigin, ConnectedPosition } from '@angular/cdk/overlay';
import { NgIf } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  OnInit,
  Output,
  ViewChild,
  booleanAttribute,
  inject,
} from '@angular/core';
import { QButtonComponent } from '@questrade/allspark-angular-components/button';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { QIconComponent } from '@questrade/allspark-angular-components/icon';
import { QOverlayComponent } from '@questrade/allspark-angular-components/overlay';
import { takeUntil } from 'rxjs';
import { QPromotionalMessagePanel } from './types/promotional-message-panel.interface';
import { QPromotionalMessagePosition } from './types/promotional-message-position.type';

@Component({
  selector: 'q-promotional-message',
  templateUrl: './promotional-message.component.html',
  styleUrls: ['./promotional-message.component.scss'],
  imports: [NgIf, QIconComponent, QOverlayComponent, QButtonComponent],
  providers: [QDestroyService],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QPromotionalMessageComponent
  implements QPromotionalMessagePanel, OnInit, AfterViewInit
{
  @Output() readonly closed = new EventEmitter<void>();

  @Input() title = '';
  @Input() message = '';
  @Input() icon = '';
  @Input() position: QPromotionalMessagePosition = 'bottom';
  @Input() primaryButtonText = '';
  @Input() secondaryButtonText = '';
  @Input({ transform: booleanAttribute }) hasSecondaryButton = false;
  @Input({ transform: booleanAttribute }) openMessageOnInit = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'promotional-message';

  @ViewChild('overlay') _overlay!: QOverlayComponent;

  @HostBinding('class') hostClass = 'q-promotional-message';

  openedBy!: CdkOverlayOrigin;
  positions: ConnectedPosition[] = [];

  private _positionsMap = {
    top: {
      originX: 'center',
      originY: 'top',
      overlayX: 'center',
      overlayY: 'bottom',
      offsetY: -10,
      panelClass: 'top',
    } as ConnectedPosition,
    right: {
      originX: 'end',
      originY: 'center',
      overlayX: 'start',
      overlayY: 'center',
      offsetX: 10,
      panelClass: 'right',
    } as ConnectedPosition,
    bottom: {
      originX: 'center',
      originY: 'bottom',
      overlayX: 'center',
      overlayY: 'top',
      offsetY: 10,
      panelClass: 'bottom',
    } as ConnectedPosition,
    left: {
      originX: 'start',
      originY: 'center',
      overlayX: 'end',
      overlayY: 'center',
      offsetX: -10,
      panelClass: 'left',
    } as ConnectedPosition,
  };
  private readonly _destroy$ = inject(QDestroyService);

  ngOnInit(): void {
    this.positions = this._getPositions();
  }

  ngAfterViewInit(): void {
    this._overlay.closed.pipe(takeUntil(this._destroy$)).subscribe(() => this.closed.emit());

    if (this.openMessageOnInit) {
      this.open();
    }
  }

  open(): void {
    if (this.isOpened) return;
    this._overlay.open();
  }

  close(): void {
    this._overlay.close();
    this.closed.emit();
  }

  _getPositions(): ConnectedPosition[] {
    if (this.position === 'right') {
      return [
        this._positionsMap.right,
        this._positionsMap.left,
        this._positionsMap.top,
        this._positionsMap.bottom,
      ];
    } else if (this.position === 'left') {
      return [
        this._positionsMap.left,
        this._positionsMap.right,
        this._positionsMap.top,
        this._positionsMap.bottom,
      ];
    } else if (this.position === 'bottom') {
      return [
        this._positionsMap.bottom,
        this._positionsMap.top,
        this._positionsMap.right,
        this._positionsMap.left,
      ];
    } else
      return [
        this._positionsMap.top,
        this._positionsMap.bottom,
        this._positionsMap.right,
        this._positionsMap.left,
      ];
  }

  get isOpened(): boolean {
    return this._overlay.isOpened;
  }
}
