import { CdkOverlayOrigin } from '@angular/cdk/overlay';
import { Directive, ElementRef, HostBinding, Input, inject } from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { takeUntil } from 'rxjs';
import { QPromotionalMessagePanel } from './types/promotional-message-panel.interface';

@Directive({
  selector: '[qPromotionalMessageTrigger]',
  providers: [QDestroyService],
})
export class QPromotionalMessageTriggerDirective {
  @Input('qPromotionalMessageTrigger') get message(): QPromotionalMessagePanel {
    return this._message;
  }
  set message(message: QPromotionalMessagePanel) {
    if (message === this._message) return;

    if (this._overlayOrigin) {
      message.openedBy = this._overlayOrigin;
    }

    this._message = message;

    this.message.closed.pipe(takeUntil(this._destroy$)).subscribe(() => {
      this._closeMessage();
    });
  }

  @HostBinding('class') hostClass = 'q-highlight-content';

  private _message!: QPromotionalMessagePanel;
  private readonly _elementRef = inject(ElementRef);
  private readonly _destroy$ = inject(QDestroyService);
  private _overlayOrigin: CdkOverlayOrigin | null = null;

  constructor() {
    this._overlayOrigin = new CdkOverlayOrigin(this._elementRef);
  }

  private _closeMessage(): void {
    if (this.message.isOpened) {
      this.message?.close();
    }
  }
}
